import pandas as pd
import matplotlib.pyplot as plt
import base64
from io import BytesIO
import numpy as np

# Load Data
print("Loading data...")
df = pd.read_csv('/app/benchmark/data.csv', low_memory=False)

# Clean Price Column
df['price'] = pd.to_numeric(df['price'], errors='coerce')

# Chart helper
def fig_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=120)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode()

# KPI computations
print("Computing metrics...")
total_listings = len(df)
city_counts = df['city'].value_counts().reset_index()
city_counts.columns = ['City', 'Listings Count']

# KPI: Median Nightly Price by City
median_price = df.dropna(subset=['price']).groupby('city')['price'].median().sort_values(ascending=False)
avg_price = df.dropna(subset=['price']).groupby('city')['price'].mean().sort_values(ascending=False)

# KPI: Professional Host Share
df['is_prof'] = df['calculated_host_listings_count'] >= 5
prof_share = (df.groupby('city')['is_prof'].mean() * 100).sort_values(ascending=False)

# KPI: Average Reviews per Month
avg_reviews = df.groupby('city')['reviews_per_month'].mean().sort_values(ascending=False)

# KPI: Mean Availability
mean_avail = df.groupby('city')['availability_365'].mean().sort_values(ascending=False)

# KPI: Entire Home Share
df['is_entire'] = df['room_type'] == 'Entire home/apt'
entire_share = (df.groupby('city')['is_entire'].mean() * 100).sort_values(ascending=False)

# Pricing charts
print("Generating charts...")
fig, ax = plt.subplots(figsize=(10, 5))
median_price.plot(kind='bar', color='#3498DB', ax=ax)
ax.set_title('Median Nightly Price by City (USD)', fontsize=14)
ax.set_ylabel('Price (USD)')
ax.set_xlabel('City')
ax.grid(axis='y', linestyle='--', alpha=0.7)
plt.xticks(rotation=45, ha='right')
chart_price_b64 = fig_to_base64(fig)

# Supply structure charts
fig, ax = plt.subplots(figsize=(10, 5))
prof_share.plot(kind='bar', color='#E67E22', ax=ax)
ax.set_title('Professional Host Share (% of Listings >= 5 properties)', fontsize=14)
ax.set_ylabel('Percentage (%)')
ax.set_xlabel('City')
ax.grid(axis='y', linestyle='--', alpha=0.7)
plt.xticks(rotation=45, ha='right')
chart_prof_b64 = fig_to_base64(fig)

# Room type distribution
room_dist = df.groupby(['city', 'room_type']).size().unstack(fill_value=0)
room_dist_pct = room_dist.div(room_dist.sum(axis=1), axis=0) * 100
fig, ax = plt.subplots(figsize=(12, 6))
room_dist_pct.plot(kind='bar', stacked=True, ax=ax, colormap='Set3')
ax.set_title('Room Type Distribution by City (%)', fontsize=14)
ax.set_ylabel('Percentage (%)')
ax.legend(title='Room Type', bbox_to_anchor=(1.05, 1), loc='upper left')
plt.xticks(rotation=45, ha='right')
chart_room_b64 = fig_to_base64(fig)

# Demand proxy: reviews per month
fig, ax = plt.subplots(figsize=(10, 5))
avg_reviews.plot(kind='bar', color='#2ECC71', ax=ax)
ax.set_title('Average Reviews per Month by City (Guest Demand Proxy)', fontsize=14)
ax.set_ylabel('Avg Reviews/Month')
ax.set_xlabel('City')
ax.grid(axis='y', linestyle='--', alpha=0.7)
plt.xticks(rotation=45, ha='right')
chart_reviews_b64 = fig_to_base64(fig)

# Availability and Min Nights
median_min_nights = df.groupby('city')['minimum_nights'].median().sort_values(ascending=False)

# Price by Room Type Table
price_by_room = df.dropna(subset=['price']).pivot_table(index='city', columns='room_type', values='price', aggfunc='median').fillna('-')
price_by_room = price_by_room.reindex(median_price.index)

